// One row per invoice in the Data Table "invoice_jobs" (columns: job_id, status, result — all text).
// The page asks for it with invoice-result?id=<job_id> every few seconds.
const j = $input.first().json;
const sid = $('Reference Data').first().json.selected?.session_id || '';
const failed = j.status === 'error' || !!j.error;
return [{ json: { job_id: sid, status: failed ? 'error' : 'done', result: JSON.stringify(failed ? { status: 'error', summary: j.summary || j.error?.message || j.error || 'القراءة فشلت' } : j) } }];

// not saved yet -> still reading; saved -> the reading result (same as before)
const row = $input.first().json || {};
if (!row.job_id) return [{ json: { reply: { status: 'reading' }, job_id: null } }];
let r; try { r = JSON.parse(row.result); } catch (e) { r = { status: 'error', summary: 'النتيجة اتخزنت ناقصة' }; }
return [{ json: { reply: r, job_id: row.job_id } }];

// Builds the Gemini request. No item list in the prompt: the model only transcribes what is written
// (fewer tokens), and the Parse node matches the names to the price list in code.
// Thinking level HIGH (lower levels made reading mistakes). Thinking tokens are billed as output — the biggest cost/speed lever.
const body = $('Analyze Request').first().json.body || {};
const PROMPT = "You read handwritten Arabic sales invoices from Egypt (company: a wholesale distribution company).
The printed table has 4 columns, right to left: اسم الصنف (item) | السعر (price) | الكمية (quantity) | الإجمالي (total).
Read the invoice exactly as written. Do NOT correct anything and do NOT calculate anything.

ROWS (top to bottom, only rows with handwriting; the large zigzag line closing empty rows is NOT a row):
- written_name: the item name exactly as written, in Arabic, including the pack-size number (12, 20, 50, 600...).
- price_raw / qty_raw / total_raw: copy every number character by character in Arabic-Indic digits, exactly as written.
  The Arabic zero "٠" is a small dot or short dash and is easy to miss — count every digit ("٦٠" = 60, "٤٨٠٠٠" = 48000).
  Prices often have fractions: "،" "," or "/" between digits is a decimal point ("١١،٥" = 11.5);
  a small fraction next to or above the number: "٢٥¼" = 25.25, "١١½" = 11.5 — include it.
  If a number is crossed out or written over, use the final value. Illegible = null.

MARGIN (handwriting below the last item, "الإجمالي فقط وقدره", "المدفوع", "المتبقي", side margins):
- subtotal, then "خصم" with an amount or a percentage, then the amount after discount. Copy only; do not calculate.

HEADER:
- customer_written: the name after "اسم العميل" exactly as written; address_written: after "العنوان".
- sales_rep_written: the name or signature after "اسم المندوب" at the bottom.
- day_raw: only the day of the month from "التاريخ" (date is day/month/year, the day is the first number).

If the photo shows more than one invoice, read only the largest / most complete one and set invoice_count_visible accordingly.

Return ONLY this JSON:
{"invoice_count_visible": 1,
 "header": {"customer_written": null, "address_written": null, "sales_rep_written": null, "day_raw": null},
 "rows": [{"row": 1, "written_name": "...", "price_raw": "٨٠٠", "qty_raw": "٦٠", "total_raw": "٤٨٠٠٠"}],
 "margin": {"subtotal_raw": null, "discount_amount": null, "discount_percent": null, "after_discount_raw": null, "all_text": ""}}";
return [{ json: { req_invoice: {
  contents: [{ role: 'user', parts: [
    { text: PROMPT },
    { inline_data: { mime_type: body.mime || 'image/jpeg', data: body.image_b64 } },
  ] }],
  generationConfig: {
    responseMimeType: 'application/json',
    maxOutputTokens: 16000,
    thinkingConfig: { thinkingLevel: 'high' },
  },
} } }];

// Reference data: price list (sent to Gemini) + customers (used only by the Parse node, NOT sent to Gemini).
// SAMPLE DATA — replace with your own price list and customer list (e.g. generated from Excel).
const catalog_items = [
 {
  "code": "ITM001",
  "name": "زيت عباد الشمس 1 لتر",
  "price": 85
 },
 {
  "code": "ITM002",
  "name": "سكر أبيض 1 كيلو",
  "price": 38
 },
 {
  "code": "ITM003",
  "name": "أرز مصري 1 كيلو",
  "price": 42
 },
 {
  "code": "ITM004",
  "name": "مكرونة 400 جم",
  "price": 18.5
 },
 {
  "code": "ITM005",
  "name": "شاي ناعم 250 جم",
  "price": 95
 },
 {
  "code": "ITM006",
  "name": "عسل نحل 450 جم",
  "price": 134
 },
 {
  "code": "ITM007",
  "name": "بلح بدون نوى 400 جم",
  "price": 100
 },
 {
  "code": "ITM008",
  "name": "Stevia 40 sachets",
  "price": 60
 },
 {
  "code": "ITM009",
  "name": "Baby drink 10 sachets",
  "price": 32
 },
 {
  "code": "ITM010",
  "name": "صابون سائل 1 لتر",
  "price": 55
 }
];
const customers = [
 {
  "id": "CUST-0001",
  "name": "ماركت النور"
 },
 {
  "id": "CUST-0002",
  "name": "صيدلية الأمل"
 },
 {
  "id": "CUST-0003",
  "name": "أسواق الخير"
 },
 {
  "id": "CUST-0004",
  "name": "عطارة البركة"
 },
 {
  "id": "CUST-0005",
  "name": "سوبر ماركت السلام"
 },
 {
  "id": "CUST-0006",
  "name": "هايبر الياسمين"
 }
];
// names only (no prices): Gemini matches by name; prices are checked in the Parse node
const customers_text = customers.map((c, i) => `${i + 1} | ${c.name}`).join('\n');
// shorter list for the prompt: the word "فلتر" repeats in most names and tells items apart in none
const catalog_text = catalog_items.map(i => `${i.code} | ${i.name.replace(/\s*فلتر\s*/g, ' ').replace(/\s+/g, ' ').trim()}`).join('\n');
// The page sends the photo as base64 JSON -> turn it into binary 'data' for the model node.
const body = $input.first().json.body || {};
let binary;
if (body.image_b64) {
  binary = { data: await this.helpers.prepareBinaryData(Buffer.from(body.image_b64, 'base64'), 'invoice.jpg', body.mime || 'image/jpeg') };
}
const selected = { customer_id: body.customer_id || null, date: body.date || null, sales_rep: body.sales_rep || '', customer_later: !!body.customer_later, session_id: body.session_id || null };
return [{ json: { catalog_items, customers, catalog_text, has_image: !!binary, selected }, ...(binary ? { binary } : {}) }];

// Parse & Validate — turns Gemini's reply into clean JSON, double-checks it, builds the Telegram message.
// Nothing is changed automatically: anything doubtful goes to review.
const MAX_DISCOUNT = 15;        // % below list price accepted as a customer discount
const MAX_ABOVE = 2.5;          // % above list price accepted (rounding)
const MAX_INVOICE_DISCOUNT = 20;// % discount on the whole invoice accepted
const MAX_DATE_AGE_DAYS = 45;   // invoices older than this go to review
const ITEM_MIN = 0.75, CUSTOMER_MIN = 0.7;
const priceOk = (p, cat) => p <= cat.price * (1 + MAX_ABOVE / 100) && p >= cat.price * (1 - MAX_DISCOUNT / 100);

// ---------- helpers ----------
const DIG = { '٠':0,'١':1,'٢':2,'٣':3,'٤':4,'٥':5,'٦':6,'٧':7,'٨':8,'٩':9 };
const toNum = (v) => {
  if (v === null || v === undefined || v === '') return null;
  let t = String(v).replace(/[٠-٩]/g, d => DIG[d]).replace(/[٫،]/g, '.');
  const frac = { '¼': 0.25, '½': 0.5, '¾': 0.75 }[(t.match(/[¼½¾]/) || [])[0]] || 0;   // "٢٥¼" = 25.25
  const n = parseFloat(t.replace(/[^\d.\-]/g, '')) + (frac && !/\./.test(t) ? frac : 0);
  return Number.isFinite(n) ? n : null;
};
const fmt = (n) => n == null ? '؟' : Number(n).toLocaleString('en-US', { maximumFractionDigits: 2 });
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// works with the OpenAI node and the Gemini node, whatever shape the reply comes in
const asText = (v) => typeof v === 'string' ? v : Array.isArray(v) ? v.map(asText).join('') : v && typeof v === 'object' ? (v.text ?? v.content ?? '') : '';
const getText = (j) =>
  asText(j.content) || asText(j.message?.content) || asText(j.choices?.[0]?.message?.content) ||
  asText(j.output) || asText(j.text) || asText(j.content?.parts) ||
  asText(j.candidates?.[0]?.content?.parts) || JSON.stringify(j);

// Arabic-aware name similarity (0..1)
const norm = (s) => String(s || '').replace(/[٠-٩]/g, d => DIG[d])
  .replace(/[ً-ْٰـ]/g, '').replace(/[أإآٱ]/g, 'ا').replace(/ة/g, 'ه')
  .replace(/ى/g, 'ي').replace(/ؤ/g, 'و').replace(/ئ/g, 'ي').replace(/ء/g, '')
  .replace(/[^\p{L}\p{N}]+/gu, ' ').trim().replace(/\s+/g, ' ').toLowerCase();
const stem = (t) => { for (const p of ['بال', 'وال', 'ال']) if (t.startsWith(p) && t.length - p.length >= 3) return t.slice(p.length); return t; };
const STOP = new Set(['فلتر', 'مغلف', 'علبه', 'جردل', 'جرادل', 'علب', 'ايزيس', 'جم', 'جرام', 'ملي', 'كيلو', 'لتر', 'ماركت', 'سوبر']);
const words = (s) => norm(s).split(' ').filter(Boolean).map(stem).filter(t => t.length > 1 && !/\d/.test(t) && !STOP.has(t));   // single letters like "ك" are units, not words
const nums = (s) => (norm(s).match(/\d+/g) || []).map(Number);
const dice = (a, b) => {
  if (a === b) return 1; if (a.length < 2 || b.length < 2) return 0;
  const A = [], B = []; for (let i = 0; i < a.length - 1; i++) A.push(a.slice(i, i + 2)); for (let i = 0; i < b.length - 1; i++) B.push(b.slice(i, i + 2));
  const n = A.length + B.length; let hit = 0;
  for (const g of A) { const k = B.indexOf(g); if (k >= 0) { hit++; B.splice(k, 1); } }
  return (2 * hit) / n;
};
const wsim = (a, b) => (a === b ? 1 : Math.min(a.length, b.length) >= 3 && (a.startsWith(b) || b.startsWith(a)) ? 0.9 : dice(a, b));
const nameScore = (raw, cand) => {
  const R = words(raw), C = words(cand); if (!R.length || !C.length) return 0;
  const cover = (X, Y) => X.reduce((s, x) => s + Math.max(...Y.map(y => wsim(x, y))), 0) / X.length;
  return 0.6 * cover(R, C) + 0.4 * cover(C, R);
};

// ---------- learned memory (filled by "Save Invoice" every time an invoice is confirmed) ----------
const memory = $getWorkflowStaticData('global');
const best = (counts) => counts ? Object.entries(counts).sort((a, b) => b[1] - a[1])[0]?.[0] : null;
const learnedItem = (written) => best(memory.items?.[norm(written)]);
const learnedCustomer = (written) => best(memory.customers?.[norm(written)]);

// ---------- reference data ----------
// find a node even if n8n added a number to its name when copying ("Reference Data1", "Reference Data2", ...)
const nodeByBase = (base) => {
  for (const name of [base, ...Array.from({ length: 9 }, (_, i) => base + (i + 1))]) {
    try { const it = $(name).first(); if (it && it.json && it.json.catalog_items !== undefined || (it && it.json && base !== 'Reference Data')) return it; } catch (e) {}
  }
  throw new Error(`node "${base}" not found`);
};
const ref = nodeByBase('Reference Data').json;
const catalog = ref.catalog_items;
const byCode = Object.fromEntries(catalog.map(c => [c.code, c]));

/** Gemini's item pick is only a hint: it must actually look like the written name. If it doesn't, the
 *  item is matched by name in code. The pack size written on the invoice must match — never changed. */
function resolveItem(it) {
  const written = it.written_name || '';
  const wNums = nums(written);
  const packOk = (c) => !wNums.length || wNums.every(n => nums(c.name).includes(n));
  // 1) confirmed before? (learned from your corrections)
  const mem = byCode[learnedItem(written)];
  if (mem) return { cat: mem, learned: true };
  const g = byCode[it.item_code];
  if (g && packOk(g) && nameScore(written, g.name) >= 0.5) return { cat: g };
  const ranked = catalog.filter(packOk).map(c => ({ c, s: nameScore(written, c.name) }))
    .sort((a, b) => b.s - a.s);
  // "جردل" / "علبة" with no size written = a kilo pack. It is the only size evidence, so it is used:
  // a non-kilo item is accepted only if its name matches exactly; otherwise only kilo items are considered,
  // and if none of them looks like the written name the line is left for you to choose (never a random item).
  const kiloWritten = /\d+ ?(ك|كيلو|كجم)( |$)/.test(norm(written));          // "5ك" / "5 كيلو" written
  const kiloHint = kiloWritten || (!wNums.length && /(^| )(جردل|جرادل|علبه|علب)( |$)/.test(norm(written)));
  if (kiloHint) {
    const isKilo = (c) => /كيلو|(^| )ك( |$)/.test(norm(c.name));
    const exact = ranked.filter(r => r.s >= 0.95);
    if (!(exact.length && !isKilo(exact[0].c))) {
      const kilo = ranked.filter(r => isKilo(r.c) && r.s >= 0.5);
      if (!kilo.length) {
        // the name was misread (e.g. "فيتا" read as "قشطه"): narrow down by what IS clear —
        // a kilo pack whose list price fits the written price — then take the closest name among those
        const price = toNum(it.price_raw) ?? toNum(it.price);
        const fits = price == null ? [] : catalog.filter(c => isKilo(c) && packOk(c) && price >= c.price * (1 - MAX_DISCOUNT / 100) && price <= c.price * (1 + MAX_ABOVE / 100));
        if (!fits.length) return { cat: null, options: [], kiloNoMatch: true };
        // the shape of the misread word still helps: same number of words and same number of letters
        // ("قشطه" = 1 word, 4 letters -> "فيتا" before "ملح خفيف" or "اسطمبولي")
        const GENERIC = new Set(['جبنه', 'طبيعي', 'طبيعى']);
        const core = (x) => words(x).filter(w => !GENERIC.has(w));
        const W = core(written);
        // letters counted as written (ء counts as a letter: "ضياء" = 4, like "فيتا")
        const asWritten = String(written).replace(/[ً-ْٰـ]/g, '').split(/\s+/)
          .filter(t => t.length > 1 && !/\d/.test(t) && !/^(جردل|جرادل|علبه|علبة|علب|كيلو|كجم)$/.test(t));
        const wLen = asWritten.join('').length || W.join('').length;
        const byName = fits.map(c => {
          const C = core(c.name);
          return { c, wd: Math.abs(C.length - W.length), ld: Math.abs(C.join('').length - wLen), s: Math.max(nameScore(written, c.name), dice(W.join(''), C.join(''))) };
        }).sort((a, b) => a.wd - b.wd || a.ld - b.ld || b.s - a.s);
        return { cat: byName[0].c, auto: true, byPrice: true, options: byName.slice(0, 8).map(r => r.c.name) };
      }
      const [k1, k2] = kilo;
      if (k1.s >= ITEM_MIN && (!k2 || k1.s - k2.s >= 0.08)) return { cat: k1.c };
      return { cat: k1.c, auto: true, options: kilo.slice(0, 3).map(r => r.c.name) };
    }
  }
  const [b1, b2] = ranked;
  if (b1 && b1.s >= ITEM_MIN && (!b2 || b1.s - b2.s >= 0.08)) return { cat: b1.c };
  // not an exact match: take the closest item anyway (Gemini's pick first, then the best name match) and flag it
  const g2 = g && packOk(g) ? g : null;
  // no word in common at all -> fall back to plain letter similarity of the whole name
  const letters = (x) => norm(x).replace(/[\d\s]/g, '');
  const byLetters = !g2 && !(b1 && b1.s > 0)
    ? catalog.filter(packOk).map(c => ({ c, s: dice(letters(written), letters(c.name)) })).sort((a, b) => b.s - a.s)[0] : null;
  const pick = g2 || (b1 && b1.s > 0 ? b1.c : null) || (byLetters ? byLetters.c : null);
  return { cat: pick, auto: !!pick, options: ranked.slice(0, 3).map(r => r.c.name) };
}

// OpenAI reasoning models return a "reasoning" block plus the actual "message" — read only the message text.
const collect = (v) => {
  if (Array.isArray(v)) return v.map(collect).join('');
  if (!v || typeof v !== 'object') return typeof v === 'string' ? v : '';
  if (v.type === 'reasoning') return '';
  if (v.type === 'output_text' || v.type === 'text') return v.text || '';
  if (v.type === 'message') return collect(v.content);
  if (Array.isArray(v.output)) return collect(v.output);        // OpenAI Responses API (HTTP Request node)
  return getText(v);
};
// ---- the 4 specialised readers (each one reads one part of the invoice) ----
// The readers' replies arrive on this node's input (from "Wait For All"), so no reader names are needed.
// Each reply is recognised by what it contains: item names, numbers, margin — or everything (single reader).
const replies = $input.all().map(i => i.json?.body ?? i.json);
const parsed = replies.map(r => {
  try {
    const text = collect(r).replace(/```json|```/g, '').trim();
    return JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1));
  } catch (e) { return null; }
}).filter(Boolean);
const rowsWith = (key) => parsed.find(p => (p.rows || []).some(r => r[key] !== undefined));
const itemsR = rowsWith('written_name') || null;
const numbersR = rowsWith('price_raw') || rowsWith('qty_raw') || null;
const headerSuggest = parsed.find(p => p.header)?.header || {};
const invoiceCount = Math.max(0, ...parsed.map(p => Number(p.invoice_count_visible) || 0));
const marginR = parsed.find(p => p.margin)?.margin
  || parsed.find(p => !p.rows && ('subtotal_raw' in p || 'after_discount_raw' in p || 'all_text' in p)) || null;
// customer, date and rep are chosen on the page by the rep — not read from the photo
const selected = ref.selected || {};
const headerR = { customer_written: headerSuggest.customer_written || '', sales_rep: selected.sales_rep || headerSuggest.sales_rep_written || '', day_raw: headerSuggest.day_raw || null };


// ---------- cost of this reading (all model calls), in EGP ----------
// Prices in USD per 1M tokens: [normal input, cached input, cache writes, output]. Output includes reasoning tokens.
const RATES = {
  'gemini-4-hydrogen': [1.50, 0.075, null, 7.50],
  'gpt-6.1-terra': [1.00, 0.05, 1.25, 5.00],
  'gpt-6-luna':    [0.10, 0.01, 0.125, 0.50],
  'gpt-6.1-sol':   [2.00, null, null, 10.00],
  'gpt-4.1-mini':  [0.40, 0.10, null, 1.60],
};
const EGP_PER_USD = 56.2;   // ← update when the dollar rate changes (NBE sell rate, late Oct 2026)
const costOf = (r) => {
  if (r?.usageMetadata) {                       // Gemini API format; thinking tokens are billed as output
    const u = r.usageMetadata, rate = RATES[String(r.modelVersion || 'gemini-4-hydrogen').replace(/-\d.*$/, '')] || RATES['gemini-4-hydrogen'];
    const cached = u.cachedContentTokenCount ?? 0;
    return (((u.promptTokenCount ?? 0) - cached) * rate[0] + cached * (rate[1] ?? rate[0]) + ((u.candidatesTokenCount ?? 0) + (u.thoughtsTokenCount ?? 0)) * rate[3]) / 1e6;
  }
  const usage = r?.usage; if (!usage) return null;
  const rate = RATES[String(r.model || '').replace(/-\d{4}-\d{2}-\d{2}$/, '')]; if (!rate) return null;
  const cached = usage.input_tokens_details?.cached_tokens ?? 0;
  const writes = usage.input_tokens_details?.cache_write_tokens ?? 0;
  const normal = (usage.input_tokens ?? 0) - cached - writes;
  return (normal * rate[0] + cached * (rate[1] ?? rate[0]) + writes * (rate[2] ?? rate[0]) + (usage.output_tokens ?? 0) * rate[3]) / 1e6;
};
const costInfo = (() => {
  let usd = 0, tokens = 0, calls = 0, unknown = 0;
  {
    for (const r of replies) {
      const c = costOf(r);
      const usage = r?.usage || r?.usageMetadata;
      if (usage) { calls++; tokens += usage.total_tokens ?? usage.totalTokenCount ?? ((usage.input_tokens ?? 0) + (usage.output_tokens ?? 0)); }
      if (c === null) { if (usage) unknown++; } else usd += c;
    }
  }
  return calls ? { cost_usd: +usd.toFixed(6), cost_egp: +(usd * EGP_PER_USD).toFixed(2), tokens, calls, cost_unknown_models: unknown } : null;
})();

// ---------- running total for the whole invoice (all readings: photo changed, retries, failed attempts) ----------
// The page adds up every reading of an invoice itself. Nothing is written to the workflow's memory here:
// readings run in parallel, and n8n saves the whole memory at the end of each run, so parallel writes
// would overwrite each other (and could wipe what was learned from your corrections).
const sessionTotal = null;

return [{ json: {} }].map(() => {
  if (!itemsR && !numbersR) return { json: { status: 'error',
    summary: '⚠️ معرفتش أقرا الفاتورة — صوّرها تاني في إضاءة كويسة ومن فوق مباشرة' } };

  // join item names and numbers by row number
  const nameRows = (itemsR?.rows || []), numRows = (numbersR?.rows || []);
  const rowNos = [...new Set([...nameRows, ...numRows].map(r => Number(r.row)).filter(n => n > 0))].sort((a, b) => a - b);
  const data = {
    // only the DAY is read; month and year are today's (previous month if the day is after today)
    date: (() => {
      const d = parseInt(toNum(headerR?.day_raw) ?? toNum(headerR?.day), 10);
      if (!(d >= 1 && d <= 31)) return null;
      const now = new Date(); let y = now.getFullYear(), m = now.getMonth() + 1;
      if (d > now.getDate()) { m -= 1; if (m === 0) { m = 12; y -= 1; } }
      return `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
    })(),
    customer_written: headerR?.customer_written || '',
    customer_no: toNum(headerR?.customer_no),
    sales_rep: headerR?.sales_rep || '',
    items: rowNos.map(n => ({ ...(nameRows.find(r => Number(r.row) === n) || {}), ...(numRows.find(r => Number(r.row) === n) || {}) })),
    subtotal_raw: marginR?.subtotal_raw ?? null,
    discount_amount: marginR?.discount_amount ?? null,
    discount_percent: marginR?.discount_percent ?? null,
    after_discount_written: marginR?.after_discount_raw ?? null,
    margin_text: marginR?.all_text || '',
  };
  const readerProblems = [];
  if (!itemsR) readerProblems.push('قارئ الأصناف مرجعش نتيجة');
  if (!numbersR) readerProblems.push('قارئ الأرقام مرجعش نتيجة');
  if (itemsR && numbersR && nameRows.length !== numRows.length)
    readerProblems.push(`عدد السطور مختلف: ${nameRows.length} اسم و ${numRows.length} سطر أرقام — راجع ترتيب السطور`);

  const issues = [];               // { row, text } — row 0 = invoice level
  const notes = [];                // automatic, confirmed corrections (shown with ℹ️)
  const add = (row, text) => issues.push({ row, text });
  readerProblems.forEach(t => add(0, t));
  if (invoiceCount > 1) add(0, `الصورة فيها ${invoiceCount} فواتير — اتقرت واحدة بس، صوّر كل فاتورة لوحدها`);

  // ---- lines ----
  const items = (data.items || []).map((it, i) => {
    const row = i + 1;
    // prefer the digit-by-digit transcription (Arabic digits) over Gemini's own conversion
    const pick = (rawV, v) => toNum(rawV) ?? toNum(v);
    let price = pick(it.price_raw, it.price); let qty = pick(it.qty_raw, it.qty); let total = pick(it.total_raw, it.total);
    // price not written (or not clear) -> total ÷ qty
    if (price == null && qty && total != null) {
      price = +(total / qty).toFixed(2);
      notes.push(`سطر ${row}: السعر مش واضح — اتحسب ${fmt(total)} ÷ ${fmt(qty)} = ${fmt(price)}`);
    }
    // quantity not written -> total ÷ price, only when it comes out a whole number
    if (qty == null && price && total != null && Math.abs(total / price - Math.round(total / price)) < 0.01) {
      qty = Math.round(total / price);
      notes.push(`سطر ${row}: الكمية مش واضحة — اتحسبت ${fmt(total)} ÷ ${fmt(price)} = ${fmt(qty)}`);
    }
    // total not written on the line -> calculate it ourselves
    if (total == null && price != null && qty != null) {
      total = +(price * qty).toFixed(2);
      notes.push(`سطر ${row}: الإجمالي مش مكتوب — اتحسب ${fmt(qty)} × ${fmt(price)} = ${fmt(total)}`);
    }
    const { cat, options, auto, learned, kiloNoMatch, byPrice } = resolveItem(it);
    if (byPrice) add(row, `"${it.written_name}" مش واضح — اتختار من السعر والحجم (جردل = كيلو)، ممكن يكون: ${options.join(' / ')}`);
  if (!cat) add(row, kiloNoMatch ? `"${it.written_name}" — صنف بالكيلو ومفيش زيه في قائمة الأسعار، اختاره بنفسك` : `الصنف "${it.written_name}" مش واضح` + (options?.length ? ` — يمكن: ${options.join(' / ')}` : ''));

    // Fractions / decimal commas are often missed ("٢٥¼" read as 25, "١١،٥" read as 11 or 115).
    // If total ÷ qty equals the read price + ¼ / ½ / ¾ (or the same digits with a decimal point), the
    // quantity and total confirm what is really written — use it and leave a note.
    if (price != null && qty && total != null && Math.abs(price * qty - total) > Math.max(1, total * 0.005)) {
      const real = total / qty;
      const frac = real - Math.floor(price);
      const fractionMissed = Math.floor(real) === Math.floor(price) && [0.25, 0.5, 0.75].some(f => Math.abs(frac - f) < 0.005);
      const decimalMissed = [10, 100].some(k => Math.abs(real * k - price) < 0.01);
      if (fractionMissed || decimalMissed) {
        notes.push(`سطر ${row}: السعر ${fmt(real)} (اتقرا ${fmt(price)} من غير الكسر)`);
        price = +real.toFixed(2);
      }
    }
    const calc = price != null && qty != null ? +(price * qty).toFixed(2) : null;
    if (calc == null || total == null || Math.abs(calc - total) > Math.max(1, total * 0.005))
      add(row, `الحساب مش مظبوط: ${fmt(qty)} × ${fmt(price)} = ${fmt(calc)} والمكتوب ${fmt(total)}`);

    let discount_pct = null;
    if (cat && price != null) {
      const diff = ((price - cat.price) / cat.price) * 100;
      if (diff > MAX_ABOVE) add(row, `السعر ${fmt(price)} أعلى من القائمة ${fmt(cat.price)}`);
      else if (diff < -MAX_DISCOUNT) add(row, `السعر ${fmt(price)} أقل من القائمة ${fmt(cat.price)} بـ ${(-diff).toFixed(0)}%`);
      else if (diff < -0.5) discount_pct = +(-diff).toFixed(1);
    }
    return { row, written_name: it.written_name, item_code: cat?.code || null, item_name: cat?.name || null, auto_picked: !!auto, learned: !!learned, by_price: !!byPrice, options: byPrice ? options : [],
      _cat: cat,
      list_price: cat?.price ?? null, price, qty, total, discount_pct };
  });

  // ---- suggestion: price far above list, but another price on this invoice (or the list price) gives the same
  //      total with a whole-number quantity -> suggest it (e.g. 20 × 1200 read, 30 × 800 written). Never applied automatically.
  const pricesSeen = items.map(x => x.price).filter(p => p != null);
  for (const x of items) {
    const cat = x._cat; delete x._cat;
    if (!cat || x.price == null || x.total == null || x.price <= cat.price * (1 + MAX_ABOVE / 100)) continue;
    const options = [...new Set([...pricesSeen, cat.price])].filter(p => p !== x.price && priceOk(p, cat));
    for (const p of options) {
      const q = x.total / p;
      if (q >= 1 && Math.abs(q - Math.round(q)) < 0.001) { x.suggestion = { qty: Math.round(q), price: p }; 
        add(x.row, `ممكن يكون ${Math.round(q)} × ${fmt(p)} = ${fmt(x.total)}`); break; }
    }
  }
  items.forEach(x => delete x._cat);

  // ---- totals (line totals are the reference; written totals are only compared, never trusted blindly) ----
  const lines_sum = +items.reduce((s, x) => s + (x.total || 0), 0).toFixed(2);
  const subtotal_written = toNum(data.subtotal_raw) ?? toNum(data.subtotal_written);
  if (subtotal_written != null && Math.abs(subtotal_written - lines_sum) > 1)
    add(0, `مجموع السطور ${fmt(lines_sum)} لكن المجموع المكتوب ${fmt(subtotal_written)}` +
      (Math.abs(subtotal_written - lines_sum * 10) <= 1 ? ' (غالباً صفر اتقرا غلط)' : ''));
  const final_written = toNum(data.after_discount_written);
  // the written after-discount amount wins (it is what the customer pays); a written amount or % is checked against it
  const writtenAmount = toNum(data.discount_amount);
  const pct = toNum(data.discount_percent);
  const fromPct = pct != null ? +(lines_sum * pct / 100).toFixed(2) : null;
  let discount = null;
  if (final_written != null && final_written <= lines_sum + 1) discount = +(lines_sum - final_written).toFixed(2);
  else if (writtenAmount != null) discount = writtenAmount;
  else if (fromPct != null) discount = fromPct;
  if (final_written != null && discount != null) {
    const other = writtenAmount ?? fromPct;
    if (other != null && Math.abs(other - discount) > Math.max(1, discount * 0.01))
      add(0, `الخصم المكتوب ${writtenAmount != null ? fmt(writtenAmount) : pct + '% = ' + fmt(fromPct)} مش مطابق للمكتوب بعد الخصم (يعني خصم ${fmt(discount)}) — اتاخد المكتوب بعد الخصم`);
  }
  const grand_total = +(lines_sum - (discount || 0)).toFixed(2);
  const discount_pct = discount ? +((discount / lines_sum) * 100).toFixed(1) : null;
  if (discount_pct != null && discount_pct > MAX_INVOICE_DISCOUNT) add(0, `خصم الفاتورة ${discount_pct}% كبير`);
  if (final_written != null && final_written > lines_sum + 1) add(0, `الصافي المكتوب ${fmt(final_written)} أكبر من مجموع السطور`);

  // ---- date (checked, never changed) ----
  // date not clear on the invoice -> today's date (a note, not a problem)
  const todayStr = new Date(Date.now() + 2 * 3600000).toISOString().slice(0, 10);   // Cairo time
  if (!data.date) notes.push(`التاريخ مش واضح في الفاتورة — اتحط تاريخ النهاردة ${todayStr}`);
  const date = data.date || todayStr;
  const age = (Date.now() - new Date(date + 'T12:00:00Z')) / 86400000;
  if (isNaN(age)) notes.push('التاريخ مش مفهوم — اتحط تاريخ النهاردة');
  else if (age < -1 || age > MAX_DATE_AGE_DAYS) add(0, `التاريخ ${date} غريب — راجعه`);

  // ---- customer: closest name in the list ----
  const written = (data.customer_written || '').trim();
  const ranked = written ? ref.customers.map(c => ({ c, s: norm(c.name) === norm(written) ? 1 : nameScore(written, c.name) }))
    .sort((a, b) => b.s - a.s).slice(0, 3) : [];
  // the header reader picked the customer from the list by letter shape — use that first
  const readerPick = data.customer_no ? ref.customers[data.customer_no - 1] : null;
  const memId = learnedCustomer(written);
  const memCustomer = memId ? ref.customers.find(c => c.id === memId) : null;
  const chosen = selected.customer_id ? ref.customers.find(c => c.id === selected.customer_id) : null;
  const bestCustomer = chosen || memCustomer || readerPick || (ranked[0] && ranked[0].s >= CUSTOMER_MIN ? ranked[0].c : null);
  if (!bestCustomer && !selected.customer_later) add(0, `العميل "${written || '؟'}" مش في القائمة` + (ranked.length ? ` — أقرب: ${ranked.map(r => r.c.name).join(' / ')}` : ''));

  // ---- Telegram message (HTML) ----
  issues.sort((a, b) => a.row - b.row);
  items.forEach(x => { x.issues = issues.filter(i => i.row === x.row).map(i => i.text); });
  const status = issues.length ? 'needs_review' : 'ready';
  const line = '━━━━━━━━━━━━━━';
  const msg = [
    status === 'ready' ? '✅ <b>الفاتورة سليمة</b>' : '⚠️ <b>الفاتورة محتاجة مراجعة</b>',
    '',
    `👤 <b>العميل:</b> ${esc(bestCustomer ? bestCustomer.name : written || '؟')}`,
    `📅 <b>التاريخ:</b> ${esc(date || '؟')}`,
    line,
    ...items.map(x => [
      `<b>${x.row}. ${esc(x.item_name || x.written_name)}</b>${x.item_name ? '' : ' ❓'}`,
      `     ${fmt(x.qty)} × ${fmt(x.price)} = <b>${fmt(x.total)}</b>${x.discount_pct ? `  <i>(خصم ${x.discount_pct}%)</i>` : ''}`,
    ].join('\n')),
    line,
    discount
      ? `المجموع: ${fmt(lines_sum)}\nالخصم: ${fmt(discount)} (${discount_pct}%)\n💰 <b>الصافي: ${fmt(grand_total)}</b>`
      : `💰 <b>الإجمالي: ${fmt(grand_total)}</b>`,
    ...(issues.length ? ['', '<b>محتاج مراجعة:</b>', ...issues.map(x => `• ${x.row ? `سطر ${x.row}: ` : ''}${esc(x.text)}`)] : []),
    ...(notes.length ? ['', ...notes.map(s => `ℹ️ ${esc(s)}`)] : []),
  ].join('\n');

  return { json: {
    status, date,
    customer_learned: !!memCustomer,
    customer_written: written, customer_id: bestCustomer?.id || null, customer_name: bestCustomer?.name || null,
    sales_rep: data.sales_rep, sales_rep_written: headerSuggest.sales_rep_written || '', address_written: headerSuggest.address_written || '', margin_text: data.margin_text,
    items, lines_sum, discount, discount_pct, grand_total,
    after_discount: final_written ?? null,
    issues: issues.map(x => (x.row ? `سطر ${x.row}: ` : '') + x.text),
    invoice_issues: issues.filter(x => !x.row).map(x => x.text), notes,
    summary: msg,
    date_read: data.date || todayStr,
    cost: costInfo,
    cost_total: sessionTotal,
  } };
});

