<script>
const CATALOG = __CATALOG__;      // [{code, name, price}]
const CUSTOMERS = __CUSTOMERS__;  // [{id, name}]
const MAX_DISCOUNT = 15, MAX_ABOVE = 2.5, MAX_INVOICE_DISCOUNT = 20;   // same rules as the Parse node
const MAX_PARALLEL = 10;          // invoices read at the same time — raise/lower to fit your Gemini rate limit

const $ = (id) => document.getElementById(id);
const byName = new Map(CATALOG.map(c => [c.name, c]));
const custByName = new Map(CUSTOMERS.map(c => [c.name, c]));
const fmt = (n) => (n == null || isNaN(n)) ? '—' : Number(n).toLocaleString('en-US', { maximumFractionDigits: 2 });
const num = (v) => { if (v === null || v === undefined || v === '') return null; const n = parseFloat(String(v).replace(',', '.')); return isFinite(n) ? n : null; };
const round2 = (n) => Math.round(n * 100) / 100;
const esc = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;');
