  if (!words.length) return [];
  return AC_SOURCES[source].filter(o => words.every(w => o.key.includes(w)))
    .sort((a, b) => (b.key.startsWith(words[0]) - a.key.startsWith(words[0])) || a.key.length - b.key.length).slice(0, 40);
