function acShow(input) {
  acInput = input; acItems = acSearch(input.dataset.ac, input.value); acOn = -1;
  if (!input.value.trim()) { acHide(); return; }
  const typed = AR(input.value);
  if (acItems.some(o => o.key === typed) && !acItems.some(o => o.key !== typed && o.key.startsWith(typed))) { acHide(); return; }
  if (!acItems.length && input.dataset.ac === 'reps') { acHide(); return; }   // a new rep name is allowed
  acBox.innerHTML = acItems.length ? acItems.map((o, k) => `<div data-k="${k}">${esc(o.label)}</div>`).join('')
    : '<div class="empty">مفيش نتايج — جرّب جزء تاني من الاسم</div>';
