  acBox.style.top = (r.bottom + window.scrollY + 4) + 'px'; acBox.style.left = (r.left + window.scrollX) + 'px';
  acBox.style.width = Math.max(r.width, 220) + 'px'; acBox.classList.remove('hidden');
}
function acHide() { acBox.classList.add('hidden'); acItems = []; acOn = -1; }
