// ======================= invoices =======================
const INV = [];          // every invoice in this batch
let seq = 0, invSeq = 0;
const avgSecs = () => { try { return Math.min(120, Math.max(8, +localStorage.getItem('invoice_avg_secs') || 30)); } catch (e) { return 30; } };
const saveSecs = (s) => { try { localStorage.setItem('invoice_avg_secs', String(Math.round((avgSecs() * 2 + s) / 3))); } catch (e) {} };

function newSession() { return Date.now().toString(36) + Math.random().toString(36).slice(2, 8); }

// photos chosen -> each one is resized and queued for reading
$('file').addEventListener('change', async (e) => {
  const files = [...e.target.files]; e.target.value = '';
  if (!files.length) return;
  showList();
  for (const f of files) {
    const inv = { id: ++invSeq, n: INV.length + 1, img: null, session: newSession(), state: 'queued', open: null, uploaded: false, st: null };
    INV.push(inv); renderList();
    inv.img = await resize(f); saveImg(inv);
    pump();
  }
});
function resize(f) {
  return new Promise((resolve) => {
    const img = new Image();
    img.onload = () => {
      const MAX = 2400, k = Math.min(1, MAX / Math.max(img.width, img.height));
      const c = document.createElement('canvas'); c.width = Math.round(img.width * k); c.height = Math.round(img.height * k);
      c.getContext('2d').drawImage(img, 0, 0, c.width, c.height);
      URL.revokeObjectURL(img.src); resolve(c.toDataURL('image/jpeg', 0.92));
    };
    img.onerror = () => resolve(null);
    img.src = URL.createObjectURL(f);
  });
}

// at most MAX_PARALLEL readings at the same time; the rest wait their turn
function pump() {
  const active = INV.filter(i => i.state === 'reading').length;
  let free = MAX_PARALLEL - active;
  for (const inv of INV) {
    if (free <= 0) break;
    if (inv.state === 'queued' && inv.img) { startReading(inv); free--; }
  }
  renderList();
}
async function startReading(inv) {
  inv.state = 'reading'; inv.started = inv.started || Date.now(); inv.error = null; saveSoon();
  try {
    // 1) send the photo — n8n answers at once with a job id and keeps reading in the background
    //    (after a reload the photo was already sent: just keep asking for the result)
    if (!inv.sent) {
      const res = await fetch('invoice-start', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ image_b64: inv.img.split(',')[1], mime: 'image/jpeg', customer_later: true, session_id: inv.session, date: today(), sales_rep: '' }),
      });
      if (!res.ok) throw new Error('HTTP ' + res.status);
      inv.sent = true; saveSoon();
    }
    // 2) ask "done yet?" every few seconds (each ask is a short request, so no Cloudflare 100 s limit)
    const r = await waitResult(inv.session);
    if (!r || r.status === 'error') throw new Error('الموديل مرجعش نتيجة');
    inv.result = r; inv.st = stateFrom(r); inv.state = 'done';
    // add this reading to the invoice's running cost (retries included)
    const c = inv.costSum = inv.costSum || { cost_usd: 0, cost_egp: 0, tokens: 0, readings: 0 };
    c.readings += 1;
    if (r.cost) { c.cost_usd += r.cost.cost_usd || 0; c.cost_egp = +(c.cost_egp + (r.cost.cost_egp || 0)).toFixed(2); c.tokens += r.cost.tokens || 0; }
    inv.st.costTotal = { ...c };
    inv.secs = Math.round((Date.now() - inv.started) / 1000); saveSecs(inv.secs);
    if (inv.st.rep && !AC_SOURCES.reps.some(o => o.label === inv.st.rep)) AC_SOURCES.reps.push({ label: inv.st.rep, key: AR(inv.st.rep) });
  } catch (err) {
    // busy / rate-limited -> try again by itself once, after a short wait
    if (!inv.autoRetried) { inv.autoRetried = true; inv.state = 'queued'; inv.sent = false; inv.started = null; saveSoon(); inv.img && setTimeout(pump, 8000); return; }
    inv.state = 'error';
    inv.error = /HTTP 5|HTTP 4|Failed to fetch|NetworkError/i.test(err.message) ? 'حصلت مشكلة في الاتصال أو في الموديل' : err.message;
  }
  inv.started = null; saveSoon();
  if (cur === inv) openInv(inv);
  pump();
}
const POLL_FIRST = 15000, POLL_EVERY = 15000, POLL_GIVE_UP = 5 * 60000;
async function waitResult(id) {
  const t0 = Date.now(); let wait = Math.max(POLL_FIRST, avgSecs() * 700), misses = 0;   // first ask a bit before the usual reading time
  while (Date.now() - t0 < POLL_GIVE_UP) {
    await new Promise(ok => setTimeout(ok, wait)); wait = POLL_EVERY;
    try {
      const res = await fetch('invoice-result?id=' + encodeURIComponent(id), { cache: 'no-store' });
      if (!res.ok) throw new Error('HTTP ' + res.status);
      const r = await res.json(); misses = 0;
      if (r && r.status !== 'reading') return r;
    } catch (e) { if (++misses >= 5) throw e; }   // a few failed asks in a row (no connection) -> give up
  }
  throw new Error('القراءة خدت أكتر من 5 دقايق');
}
function stateFrom(r) {
  const rows = (r.items || []).map(it => {
    const total = it.total ?? (it.qty != null && it.price != null ? round2(it.qty * it.price) : null);
    return { id: ++seq, written: it.written_name || '', cat: byName.get(it.item_name) || null, qty: it.qty ?? null, price: it.price ?? null,
             total, auto: !!it.auto_picked, learned: !!it.learned, suggestion: it.suggestion || null, byPrice: !!it.by_price, options: it.options || [] };
  });
  const lines = rows.reduce((s, x) => s + (x.total || 0), 0);
  const net = r.after_discount ?? (r.discount ? round2(lines - r.discount) : null);
  return { rows, customer: custByName.get(r.customer_name) ? r.customer_name : '', customerSuggested: !!custByName.get(r.customer_name),
    customerWritten: r.customer_written || '', rep: (r.sales_rep_written || '').trim(), date: r.date_read || today(),
    net: net ?? '', netTouched: net != null, invoiceIssues: r.invoice_issues || [], notes: r.notes || [], margin: r.margin_text || '',
    cost: r.cost || null, costTotal: r.cost_total || null };
}

// ----- checks (same rules as before, no DOM) -----
// qty × price ≠ total: which number is most likely misread? (the total is taken as written)
function fixOf(row) {
  const { qty, price, total } = row; if (!qty || !price || total == null) return null;
  if (row.suggestion && Math.abs(row.suggestion.qty * row.suggestion.price - total) < 1)
    return { qty: row.suggestion.qty, price: row.suggestion.price, field: row.suggestion.qty !== qty ? 'qty' : 'price' };
  const q = total / price, p = total / qty;
  const qOk = Math.abs(q - Math.round(q)) < 0.01 && q > 0;
  const near = (x) => row.cat && Math.abs(x - row.cat.price) / row.cat.price;
  // price close to the list price -> the quantity is the misread one; otherwise the price
  if (qOk && (!row.cat || near(price) <= near(p))) return { qty: Math.round(q), price, field: 'qty' };
  if (p > 0) return { qty, price: round2(p), field: 'price' };
  return null;
}
function check(row) {
  const m = [];
  if (!row.cat) m.push(['bad', row.written ? `"${row.written}" مش في القائمة — اختار الصنف` : 'اختار الصنف']);
  if (row.qty == null || row.qty <= 0) m.push(['bad', 'الكمية ناقصة']);
  if (row.price == null) m.push(['bad', 'السعر ناقص']);
  if (row.qty != null && row.price != null && row.total != null && Math.abs(row.qty * row.price - row.total) > Math.max(1, row.total * 0.005)) {
    const f = fixOf(row);
    m.push(['bad', f ? `الصح غالبًا: ${fmt(f.qty)} × ${fmt(f.price)} = ${fmt(row.total)} — مكتوب: ${f.field === 'qty' ? 'الكمية ' + fmt(row.qty) : 'السعر ' + fmt(row.price)}`
      : `${fmt(row.qty)} × ${fmt(row.price)} = ${fmt(row.qty * row.price)} مش ${fmt(row.total)}`]);
  }
  if (row.cat && row.auto && row.byPrice) m.push(['warn', `الاسم "${row.written}" مش واضح — اختارت من السعر والحجم (فيه ${row.options.length} أصناف بنفس السعر) — اتأكد منه`]);
  else if (row.cat && row.auto) m.push(['warn', `اختارت أقرب صنف للمكتوب${row.written ? ` "${row.written}"` : ''} — اتأكد منه`]);
  if (row.cat && row.price != null) {
    const d = (row.price - row.cat.price) / row.cat.price * 100;
    if (d > MAX_ABOVE) m.push(['warn', `أعلى من سعر القائمة (${fmt(row.cat.price)}) بـ ${d.toFixed(0)}%`]);
    else if (d < -MAX_DISCOUNT) m.push(['warn', `أقل ${(-d).toFixed(0)}% من سعر القائمة (${fmt(row.cat.price)})`]);
    else if (d < -0.5) m.push(['info', `أقل ${(-d).toFixed(1)}%`]);
  }
  if (row.cat && row.learned) m.push(['info', '🧠 اتعرف من تصحيح سابق']);
  const level = m.some(x => x[0] === 'bad') ? 'bad' : m.some(x => x[0] === 'warn') ? 'warn' : '';
  return { level, msgs: m };
}
function totalsOf(st) {
  const sum = round2(st.rows.reduce((s, r) => s + (r.total || 0), 0));
  const net = st.netTouched ? (num(st.net) ?? sum) : sum;
  return { sum, net, disc: round2(sum - net), pct: sum ? (sum - net) / sum * 100 : 0 };
}
function evaluate(st) {
  let errors = 0, warnings = 0;
  st.rows.forEach(r => { r._c = check(r); if (r._c.level === 'bad') errors++; else if (r._c.level === 'warn') warnings++; });
  const t = totalsOf(st);
  const cust = custByName.get(st.customer);
  if (t.net > t.sum + 0.01) errors++; else if (t.pct > MAX_INVOICE_DISCOUNT) warnings++;
  if (!cust) errors++;
  if (!st.date) errors++;
  if (!st.rows.length) errors++;
