// what the list shows for an invoice
function statusOf(inv) {
  if (inv.uploaded) return 'uploaded';
  if (inv.state === 'queued' || inv.state === 'reading') return 'reading';
  if (inv.state === 'error') return 'bad';
  const v = evaluate(inv.st);
  return v.errors ? 'bad' : v.warnings ? 'warn' : 'ready';
