const matchStatus = (inv, s = F.status) => { const k = statusOf(inv); return s === 'all' || (s === 'review' ? isReview(k) : k === s); };
const matchRep = (inv, r = F.rep) => r === '__all' || repOf(inv) === r;
const visible = () => INV.filter(i => matchStatus(i) && matchRep(i));

function showList() {
  $('uploadView').classList.add('hidden'); $('reviewView').classList.add('hidden'); $('listView').classList.remove('hidden');
  $('addPhotosTop').classList.remove('hidden'); $('title').textContent = 'الفواتير'; cur = null; closeSheets(); renderList();
}
function renderDropdowns() {
  const pool = INV.filter(i => matchRep(i));
  const sOpts = STATUS_OPTS.map(([k, l]) => [k, l, pool.filter(i => matchStatus(i, k)).length]);
  const reps = [...new Set(INV.map(repOf).filter(Boolean))].sort();
  const poolR = INV.filter(i => matchStatus(i));
  const rOpts = [['__all', 'كل المندوبين', poolR.length], ...reps.map(r => [r, r, poolR.filter(i => repOf(i) === r).length])];
  if (INV.some(i => i.st && !repOf(i))) rOpts.push(['', '❓ بدون مندوب', poolR.filter(i => i.st && !repOf(i)).length]);
  if (!rOpts.some(o => o[0] === F.rep)) F.rep = '__all';
  fillDD('ddStatus', sOpts, F.status, (k) => { F.status = k; renderList(); });
  fillDD('ddRep', rOpts, F.rep, (k) => { F.rep = k; renderList(); });
