function fillDD(id, opts, value, onPick) {
  const dd = $(id), cur0 = opts.find(o => o[0] === value) || opts[0];
  dd.querySelector('.lbl').textContent = cur0[1]; dd.querySelector('small').textContent = cur0[2];
