      <span class="chip c-read">${inv.state === 'reading' ? '<span class="ring"></span>بتتقري' : '⏸ في الدور'}</span></div></div>`;
  }
  if (inv.state === 'error') {
    return `<div class="icard bad" data-inv="${inv.id}"><div class="ch">${thumb}<div class="who"><b class="none">${IC_STORE}القراءة فشلت</b><span class="rep">${esc(inv.error || '')}</span></div>
