    : `<span class="chip c-warn">⚠️ ${probs ? (probs === 1 ? 'صنف' : probs === 2 ? 'صنفين' : probs + ' أصناف') + ' للمراجعة' : 'للمراجعة'}</span>`;
  const name = st.customer ? `<b>${IC_STORE}${esc(st.customer)}${st.customerSuggested ? ' <span title="مقترح من الفاتورة" style="font-size:.8em">💡</span>' : ''}</b>`
