  const disc = v.t.disc > 0 ? `<div class="disc"><span>المجموع ${fmt(v.t.sum)}</span><span>خصم <b>${fmt(v.t.disc)} (${v.t.pct.toFixed(1)}%)</b></span></div>` : '';
  return `<div class="icard ${s}" data-inv="${inv.id}"><div class="ch">${thumb}<div class="who">${name}${repLine}</div>${chip}</div>
    ${table}${disc}<div class="foot"><button class="toggle" data-toggle="${inv.id}" type="button">${open ? '▴ إخفاء الأصناف' : `▾ الأصناف (${st.rows.length})`}</button><span>الصافي <b>${fmt(v.t.net)}</b></span></div></div>`;
}

function renderList() {
