  $('sumline').innerHTML = `<b>${scoped.length}</b> فواتير · <span class="g"><b>${c('ready')}</b> جاهزة</span> · <span class="y"><b>${c('review')}</b> مراجعة</span> · <span class="bl"><b>${c('reading')}</b> بتتقري</span>`
