// ======================= keep the batch in this browser (reload / close and come back) =======================
// Photos and every invoice's state are kept in IndexedDB on this phone/browser. Readings that were running keep
// going in n8n, so after a reload the page just asks for their result again (nothing is read or paid twice).
const DB_NAME = 'invoice-batch', KEEP_DAYS = 2;
let dbp = null;
function db() {
  if (!dbp) dbp = new Promise((ok, no) => {
    const rq = indexedDB.open(DB_NAME, 1);
    rq.onupgradeneeded = () => { rq.result.createObjectStore('imgs'); rq.result.createObjectStore('meta'); };
    rq.onsuccess = () => ok(rq.result); rq.onerror = () => no(rq.error);
  });
  return dbp;
}
async function idb(store, mode, fn) {
  try { const d = await db(); return await new Promise((ok, no) => { const t = d.transaction(store, mode); const r = fn(t.objectStore(store)); t.oncomplete = () => ok(r && r.result); t.onerror = () => no(t.error); }); }
  catch (e) { console.log('storage', e); return null; }
}
const saveImg = (inv) => inv.img && idb('imgs', 'readwrite', s => s.put(inv.img, inv.id));
const packRow = (r) => ({ id: r.id, written: r.written, cat: r.cat ? r.cat.code : null, qty: r.qty, price: r.price, total: r.total, auto: r.auto, learned: r.learned,
  suggestion: r.suggestion, byPrice: r.byPrice, options: r.options });
const byCode = new Map(CATALOG.map(c => [c.code, c]));
function packInv(inv) {
  const { img, controller, ...o } = inv;
  if (o.st) o.st = { ...o.st, rows: o.st.rows.map(packRow) };
  return o;
}
let saveTimer = null;
function saveSoon() { clearTimeout(saveTimer); saveTimer = setTimeout(() => idb('meta', 'readwrite', s => s.put({ at: Date.now(), seq, invSeq, list: INV.map(packInv) }, 'batch')), 300); }
async function restore() {
  const meta = await idb('meta', 'readonly', s => s.get('batch'));
  if (!meta || !meta.list || !meta.list.length) return;
  // all photos in one go (much faster than one by one)
  const imgs = new Map();
  try {
    const d = await db();
    await new Promise((ok, no) => {
      const t = d.transaction('imgs', 'readonly'), s = t.objectStore('imgs'), a = s.getAll(), k = s.getAllKeys();
      t.oncomplete = () => { k.result.forEach((key, i) => imgs.set(key, a.result[i])); ok(); }; t.onerror = () => no(t.error);
    });
  } catch (e) { console.log('storage', e); }
  if (Date.now() - meta.at > KEEP_DAYS * 86400000) { clearAll(); return; }
  seq = meta.seq || 0; invSeq = meta.invSeq || 0;
  for (const o of meta.list) {
    if (o.st) o.st.rows = o.st.rows.map(r => ({ ...r, cat: r.cat ? byCode.get(r.cat) || null : null }));
    if (o.state === 'reading') o.state = 'queued';          // sent ones resume asking, unsent ones are sent again
    o.img = imgs.get(o.id) || null;
    if (!o.img && o.state === 'queued') { o.state = 'error'; o.error = 'الصورة ضاعت — صوّرها تاني'; }
    INV.push(o);
    if (o.st && o.st.rep && !AC_SOURCES.reps.some(x => x.label === o.st.rep)) AC_SOURCES.reps.push({ label: o.st.rep, key: AR(o.st.rep) });
  }
  showList(); pump();
