// The confirmed (and possibly corrected) invoice from the page arrives here.
// LEARNING: every confirmed line teaches "this handwriting = this item", and the same for the customer.
// Stored in the workflow's own memory (static data) — kept between runs of the ACTIVE workflow
// (runs from the editor's test URL do not save it).
const inv = $input.first().json.body || {};
