const rc = inv.reading_cost;   // sum of all readings of this invoice, added up by the page
const total_cost = rc && rc.cost_usd != null ? { cost_usd: +rc.cost_usd.toFixed(6), cost_egp: +(rc.cost_usd * EGP_PER_USD).toFixed(2), tokens: rc.tokens, readings: rc.readings } : null;

const invoice_no = 'INV-' + new Date().toISOString().slice(0, 10).replace(/-/g, '') + '-' + Math.floor(Math.random() * 9000 + 1000);
// Next step: save the invoice itself — Postgres / Google Sheets / ERPNext draft.
return [{ json: { ok: true, invoice_no, total_cost, learned_items: learnedItems, learned_customer: learnedCustomer, invoice: inv } }];

// Shows what the system has learned so far (open /webhook/invoice-memory in the browser).
// To forget one entry: /webhook/invoice-memory?forget=<written text>
const memory = $getWorkflowStaticData('global');
